<?php
require __DIR__.'/includes/bootstrap.php';require_permission('employees.view');$pdo=db();
$assignmentSql="SELECT id task_id,primary_assignee_id employee_id FROM tasks WHERE primary_assignee_id IS NOT NULL UNION SELECT task_id,employee_id FROM task_assignees";
$employees=$pdo->query("SELECT e.*,d.name department,u.account_status,r.name role_name,r.id role_id,r.slug role_slug,COALESCE(tp.total_tasks,0) total_tasks,COALESCE(tp.completed_tasks,0) completed_tasks,COALESCE(tp.avg_progress,0) avg_progress FROM employees e LEFT JOIN departments d ON d.id=e.department_id LEFT JOIN users u ON u.id=e.user_id LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id LEFT JOIN (SELECT a.employee_id,COUNT(t.id) total_tasks,SUM(CASE WHEN t.status='completed' THEN 1 ELSE 0 END) completed_tasks,ROUND(COALESCE(AVG(t.progress),0),1) avg_progress FROM ($assignmentSql) a JOIN tasks t ON t.id=a.task_id AND t.status<>'cancelled' GROUP BY a.employee_id) tp ON tp.employee_id=e.id ORDER BY e.created_at DESC")->fetchAll();
$departments=$pdo->query('SELECT * FROM departments WHERE is_active=1 ORDER BY name')->fetchAll();$roles=$pdo->query("SELECT * FROM roles WHERE slug<>'super_admin' ORDER BY name")->fetchAll();
$editEmployee=null;$editId=(int)($_GET['edit']??0);if($editId&&can('employees.manage')){foreach($employees as $row){if((int)$row['id']===$editId){$editEmployee=$row;break;}}}
$title='Employee Management';$active='employees';include __DIR__.'/includes/header.php';
?>
<section class="section-toolbar reveal"><div><p class="eyebrow">People operations</p><h2>Employee management</h2><p class="muted">Full CRUD for employee accounts, roles, departments, status, and task-performance visibility.</p></div><?php if(can('employees.manage')):?><button class="btn btn-primary" data-modal-open="employeeModal"><i data-lucide="user-round-plus"></i>Add employee</button><?php endif;?></section>
<section class="card-grid employee-grid reveal stagger-1"><?php if(!$employees):?><div class="panel empty-state"><i data-lucide="users"></i><h4>No employees yet</h4><p>Create the first operational employee account.</p></div><?php else:foreach($employees as $emp):$taskTotal=(int)$emp['total_tasks'];$taskDone=(int)$emp['completed_tasks'];$taskPct=$taskTotal>0?round(($taskDone/$taskTotal)*100,1):0;?><article class="employee-card"><div class="employee-card-top"><span class="avatar large"><?=e(strtoupper(substr($emp['full_name'],0,1)))?></span><span class="status-chip <?=$emp['account_status']==='active'?'on-track':'neutral'?>"><?=e(ucfirst($emp['account_status']??'inactive'))?></span></div><h3><?=e($emp['full_name'])?></h3><p><?=e($emp['job_title']?:'Team member')?> · <?=e($emp['department']?:'No department')?></p><div class="employee-meta"><span><i data-lucide="mail"></i><?=e($emp['work_email'])?></span><span><i data-lucide="shield"></i><?=e($emp['role_name']?:'No role')?></span><span><i data-lucide="badge"></i><?=e($emp['employee_code'])?></span></div><div class="admin-employee-progress"><div><span>Task completion</span><strong><?=number_format($taskPct,1)?>%</strong></div><div class="admin-progress-track"><i style="width:<?=min(100,max(0,$taskPct))?>%"></i></div><small><?=number_format($taskDone)?> completed of <?=number_format($taskTotal)?> assigned · <?=number_format((float)$emp['avg_progress'],1)?>% average progress</small></div>
<?php if(can('employees.manage')):?><div class="toolbar-actions"><a class="btn btn-soft btn-xs" href="?edit=<?=$emp['id']?>"><i data-lucide="pencil"></i>Edit</a><?php if((int)$emp['user_id']!==current_user_id()):?><form method="post" action="<?=e(url('handlers/employee-toggle.php'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$emp['id']?>"><button class="btn btn-soft btn-xs" data-confirm="Change this employee account status?"><?=$emp['account_status']==='active'?'Deactivate':'Reactivate'?></button></form><form method="post" action="<?=e(url('handlers/employee-delete.php'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$emp['id']?>"><button class="btn btn-danger btn-xs" data-confirm="Delete <?=e($emp['full_name'])?>? Assigned tasks and drivers will be safely unlinked."><i data-lucide="trash-2"></i>Delete</button></form><?php endif;?></div><?php endif;?></article><?php endforeach;endif;?></section>
<div class="modal" id="employeeModal" aria-hidden="true"><div class="modal-card"><button class="modal-close" data-modal-close><i data-lucide="x"></i></button><p class="eyebrow">Team access</p><h3>Create employee account</h3><form class="form-grid" method="post" action="<?=e(url('handlers/employee-save.php'))?>"><?=csrf_field()?><label class="span-2">Full name<input name="full_name" required></label><label>Work email<input type="email" name="work_email" required></label><label>Temporary password<input type="password" name="password" minlength="10" required></label><label>Contact number<input name="contact_number"></label><label>Job title<input name="job_title"></label><label>Department<select name="department_id"><option value="">Select</option><?php foreach($departments as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach;?></select></label><label>Role<select name="role_id" required><?php foreach($roles as $r):?><option value="<?=$r['id']?>"><?=e($r['name'])?></option><?php endforeach;?></select></label><label>Joining date<input type="date" name="joining_date" value="<?=e(date('Y-m-d'))?>"></label><div class="form-actions span-2"><button type="button" class="btn btn-soft" data-modal-close>Cancel</button><button class="btn btn-primary">Create employee</button></div></form></div></div>
<?php if($editEmployee):?><div class="modal open" aria-hidden="false"><div class="modal-card"><a class="modal-close" href="<?=e(url('employees.php'))?>"><i data-lucide="x"></i></a><p class="eyebrow">Employee CRUD</p><h3>Edit <?=e($editEmployee['employee_code'])?></h3><form class="form-grid" method="post" action="<?=e(url('handlers/employee-update.php'))?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$editEmployee['id']?>"><label class="span-2">Full name<input name="full_name" value="<?=e($editEmployee['full_name'])?>" required></label><label>Work email<input type="email" name="work_email" value="<?=e($editEmployee['work_email'])?>" required></label><label>Contact number<input name="contact_number" value="<?=e($editEmployee['contact_number']??'')?>"></label><label>Job title<input name="job_title" value="<?=e($editEmployee['job_title']??'')?>"></label><label>Department<select name="department_id"><option value="">Select</option><?php foreach($departments as $d):?><option value="<?=$d['id']?>" <?=((int)$editEmployee['department_id']===(int)$d['id'])?'selected':''?>><?=e($d['name'])?></option><?php endforeach;?></select></label><label>Role<?php if(($editEmployee['role_slug']??'')==='super_admin'):?><input value="Super Administrator" disabled><input type="hidden" name="role_id" value="<?=$editEmployee['role_id']?>"><?php else:?><select name="role_id"><?php foreach($roles as $r):?><option value="<?=$r['id']?>" <?=((int)$editEmployee['role_id']===(int)$r['id'])?'selected':''?>><?=e($r['name'])?></option><?php endforeach;?></select><?php endif;?></label><label>Employment status<select name="employment_status"><?php foreach(['active','inactive','on_leave'] as $s):?><option value="<?=$s?>" <?=$editEmployee['employment_status']===$s?'selected':''?>><?=e(ucwords(str_replace('_',' ',$s)))?></option><?php endforeach;?></select></label><label>Joining date<input type="date" name="joining_date" value="<?=e($editEmployee['joining_date']??'')?>"></label><div class="form-actions span-2"><a class="btn btn-soft" href="<?=e(url('employees.php'))?>">Cancel</a><button class="btn btn-primary">Update employee</button></div></form></div></div><?php endif;?>
<?php include __DIR__.'/includes/footer.php';?>
